public class Main {
    static boolean isArmstrong(int n) {
        int digits = String.valueOf(n).length();
        int sum = 0;
        for (int rest = n; rest > 0; rest /= 10) {
            int power = 1;
            for (int i = 0; i < digits; i++) {
                power *= rest % 10;
            }
            sum += power;
        }
        return sum == n;
    }

    public static void main(String[] args) {
        for (int n = 100; n < 1000; n++) {
            if (isArmstrong(n)) {
                System.out.println(n);
            }
        }
    }
}
